(()=>{const cards=document.querySelector('#cards');const reduce=matchMedia('(prefers-reduced-motion: reduce)');let raf=0;const stage=document.createElement('div');stage.className='assembly-stage';cards.before(stage);stage.append(cards);function paint(){raf=0;const items=[...cards.querySelectorAll('.card')];const h=document.querySelector('#header').offsetHeight;stage.style.setProperty('--gallery-top',h+'px');const r=stage.getBoundingClientRect();const p=Math.max(0,Math.min(1,(h-r.top)/Math.max(1,r.height-cards.offsetHeight)));items.forEach((el,i)=>{const q=reduce.matches?1:Math.max(0,Math.min(1,p*items.length-i));const t=q*q*(3-2*q);const x=el.offsetLeft+el.offsetWidth/2;const y=el.offsetTop+el.offsetHeight/2;el.style.opacity=q>0?1:0;el.style.transform=`translate(${(cards.clientWidth/2-x)*(1-t)}px,${(cards.clientHeight/2-y)*(1-t)}px) scale(${.78+.22*t})`;el.style.zIndex=q<1?20:1;el.inert=q<.99;});}function queue(){if(!raf)raf=requestAnimationFrame(paint)}new MutationObserver(queue).observe(cards,{childList:true});addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);reduce.addEventListener('change',queue);queue()})();
